import { useRef } from 'react';
import { Menu, UserRound } from 'lucide-react';
import { AdministratorShortcut } from './administrator-access';
type Props = { accountIcon?:boolean; onRadar?:()=>void; onAlerts:()=>void; onInstall:()=>void; onService:()=>void; onContribute:()=>void; onCities:()=>void; onNews?:()=>void; onPeople:()=>void; onAdvertise:()=>void };
export function SiteMenu(props:Props) {
  const menu=useRef<HTMLDetailsElement>(null);
  function close(){if(menu.current)menu.current.open=false;}
  function action(callback:()=>void){close();callback();}
  return <details className='tcSiteMenu' ref={menu} onKeyDown={event=>{
    if(event.key==='Escape'){close();menu.current?.querySelector('summary')?.focus();event.stopPropagation();}
  }}>
    <summary aria-label='Abrir menú de Trabajo Cerca'>{props.accountIcon?<UserRound aria-hidden='true'/>:<Menu aria-hidden='true'/>}<span>Menú</span></summary>
    <div className='tcSiteMenuPanel' role='region' aria-label='Menú de Trabajo Cerca'>
      <nav aria-label='Más opciones'>
        <button onClick={()=>action(props.onAdvertise)}>Promocionar mi negocio</button>
        <button onClick={()=>action(props.onPeople)}>Ver personas y oficios</button>
        <button onClick={()=>action(props.onService)}>Necesito un servicio</button>
        <button onClick={()=>action(props.onRadar??(()=>document.getElementById('neo-radar')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})))}>Radar territorial</button>
        <button onClick={()=>action(props.onCities)}>Buscar en otras ciudades</button>
        {props.onNews&&<button onClick={()=>action(props.onNews!)}>Actualidad laboral</button>}
        <button onClick={()=>action(props.onContribute)}>Compartir un aviso con el Radar</button>
        <button onClick={()=>action(props.onAlerts)}>Configurar avisos</button>
        <button onClick={()=>action(props.onInstall)}>Instalar app</button>
      </nav>
      <AdministratorShortcut inline/>
      <button className='tcCloseSiteMenu' onClick={()=>{close();menu.current?.querySelector('summary')?.focus();}}>Cerrar menú principal</button>
    </div>
  </details>;
}

import {useState, type ReactNode} from 'react';

type CampaignView = {id:string; label:string; banner:ReactNode};
/** Present allocated slots in Stitch's single editorial viewport.
 * Only the visible banner intersects; mounted observers keep their per-creative deduplication.
 * No additional campaign is selected, no timer rotates inventory, and paid slots stay outside.
 */
export function StitchAdvertising({campaigns}:{campaigns:CampaignView[]}) {
  const [selected,setSelected]=useState('search');
  const active=campaigns.find(c=>c.id===selected)??campaigns[0];
  if(!active)return null;
  return <div className='tcCampaignViewport'>
    <div className='tcCampaignSelector' role='group' aria-label='Campañas disponibles'>
      {campaigns.map(c=><button key={c.id} type='button' aria-pressed={active.id===c.id} aria-controls={'tc-editorial-'+c.id} onClick={()=>setSelected(c.id)}>{c.label}</button>)}
    </div>
    {campaigns.map(c=><div key={c.id} id={'tc-editorial-'+c.id} hidden={active.id!==c.id}>{c.banner}</div>)}
  </div>;
}

/** Identidad común de Trabajo Cerca en web, PWA y secciones de la aplicación. */
export function StitchBrand({subtitle='Inicio'}:{subtitle?:string}) {
  return <span className='tcStitchBrand tcUnifiedBrand' aria-label='Trabajo Cerca'>
    <img className='tcStitchBrandArt' src='/brand/trabajo-cerca-simbolo.svg'
      width='64' height='64' alt='' decoding='async'/>
    <span className='tcOfficialBrandName'>Trabajo Cerca</span>
    <span className='tcBrandSubtitle' aria-hidden='true'>{subtitle}</span>
  </span>;
}

import {ArrowRight, BadgeCheck, LockKeyhole, MapPin, PlusCircle, UserRoundSearch, Wrench} from 'lucide-react';

type Person = {id:string; title:string; workLocation:string; note:string};

/** Stitch's community block, populated only from public, approved profiles. */
export function StitchCommunity({person, onOffer, onBrowse, onSelect}:{
  person?:Person; onOffer:()=>void; onBrowse:()=>void; onSelect:(id:string)=>void;
}) {
  return <section className='tcStitchCommunity' aria-labelledby='tc-community-title'>
    <div className='tcStitchCommunityInner'>
      <div className='tcCommunityCopy'>
        <span className='tcStitchEyebrow'><Wrench aria-hidden='true'/> <span className='tcDesktopText'>Comunidad de Oficios Locales</span><span className='tcMobileText'>Fricción cero</span></span>
        <h2 id='tc-community-title'>¿Sabes hacer algo? <span>Que te encuentren<span className='tcDesktopText'> en tu comuna.</span></span></h2>
        <p><span className='tcDesktopText'>Electricidad, costura, jardinería, clases, mecánica y servicios profesionales. Publica gratis tu perfil para que te puedan contratar. Tú acuerdas la remuneración de tu trabajo.</span><span className='tcMobileText'>Publica gratis tu perfil y conecta con personas que necesiten tus servicios. Tú acuerdas cuánto cobrar por tu trabajo.</span></p>
        <div className='tcCommunityBenefits'>
          <div><BadgeCheck aria-hidden='true'/><b>Publicación gratis</b><small>Sin comisiones por contacto ni cobros ocultos.</small></div>
          <div><LockKeyhole aria-hidden='true'/><b>Contacto directo</b><small>Con permisos y datos de contacto protegidos.</small></div>
          <div><Wrench aria-hidden='true'/><b>Todos los oficios</b><small>Desde reparaciones hasta servicios técnicos.</small></div>
        </div>
        <button type='button' className='tcCommunityOffer' onClick={onOffer}><PlusCircle aria-hidden='true'/> Publicar mi perfil gratis</button><small className='tcCommunityFreeNote'>La publicación es gratuita; tú acuerdas el valor de tu trabajo.</small>
      </div>
      <aside className='tcCommunityProfile' aria-label='Personas y oficios locales'>
        <div className='tcCommunityProfileTop'><span>Personas y oficios</span><UserRoundSearch aria-hidden='true'/></div>
        {person ? <>
          <h3>{person.title}</h3><p className='tcCommunityLocation'><MapPin aria-hidden='true'/>{person.workLocation}</p>
          <p className='tcCommunityDescription'>{person.note || 'Consulta el perfil para conocer su disponibilidad y forma de contacto.'}</p>
          <button type='button' onClick={()=>onSelect(person.id)}>Ver perfil <ArrowRight aria-hidden='true'/></button>
        </> : <>
          <h3>Tu oficio tiene un lugar aquí.</h3><p className='tcCommunityDescription'>Publica lo que sabes hacer y dónde puedes trabajar. Los perfiles disponibles se muestran en el catálogo.</p>
          <button type='button' onClick={onBrowse}>Ver personas y oficios <ArrowRight aria-hidden='true'/></button>
        </>}
      </aside>
    </div>
  </section>;
}

/* Literal layout measurements from the three approved Stitch code.html files.
   Sole owner of public home geometry. Green brand mapping follows owner direction.
   Dialogs, operations, SDK, advertising allocation and PWA are independent. */
/* Usar las fuentes del sistema hasta que se adjunten los archivos tipográficos licenciados. */
.tcStitchShell{
  --st-surface:#f7f9f6;--st-low:#eef4eb;--st-high:#e0ecd7;--st-line:#d7dfd4;
  --st-ink:#103529;--st-muted:#4a584e;--st-green:#267447;--st-lime:#b9ee67;
  --neo-bg:var(--st-surface);--neo-paper:#fff;--neo-ink:var(--st-ink);--neo-ink-soft:var(--st-muted);
  --neo-lime:var(--st-lime);--neo-mint:var(--st-high);--neo-cyan:var(--st-green);--neo-coral:#8b543c;--neo-line:var(--st-line);
  margin:0;padding:64px 0 0;min-height:100dvh;width:100%;max-width:none;
  background:var(--st-surface);color:var(--st-ink);font:400 14px/22px Inter,Arial,sans-serif;
}
.tcStitchShell *,.tcStitchShell *::before,.tcStitchShell *::after{box-sizing:border-box}
.tcStitchShell button,.tcStitchShell input,.tcStitchShell select{font:inherit}
.tcStitchShell button{cursor:pointer}
.tcStitchShell button:disabled{opacity:.5;cursor:default}
.tcStitchShell button:focus-visible,.tcStitchShell a:focus-visible,.tcStitchShell select:focus-visible,.tcStitchShell input:focus-visible,.tcStitchShell summary:focus-visible{outline:3px solid var(--st-green);outline-offset:3px}
.tcStitchShell h1,.tcStitchShell h2,.tcStitchShell h3{font-family:'Plus Jakarta Sans',Inter,sans-serif;font-weight:600;color:inherit}
.tcStitchShell svg{flex-shrink:0;width:20px;height:20px}
.tcStitchShell section[id]{scroll-margin-top:80px}
.tcStitchShell .tcMobileText,.tcStitchShell .tcMobilePlace{display:none}
.tcStitchShell .neoTopbar{position:fixed;inset:0 0 auto;z-index:60;display:block;height:64px;min-height:64px;padding:0;background:#ffffffed;border:0;box-shadow:0 1px 8px #0000000a;backdrop-filter:blur(20px)}
.tcStitchShell .tcTopbarInner{max-width:1092px;height:64px;margin:auto;padding:0 40px;display:flex;align-items:center;justify-content:space-between;gap:24px}
.tcStitchShell .neoBrand{display:block;flex-shrink:0;border:0;padding:0;background:none;text-align:left;min-width:0}
.tcStitchShell .tcStitchBrand{display:block;width:178px;line-height:0}
.tcStitchShell .tcStitchBrandArt{display:block}
.tcStitchShell .tcStitchBrand img{display:block;width:100%;height:40px;max-height:none;object-fit:contain;object-position:left center}
.tcStitchShell .tcStitchMobileWordmark{display:none}
.tcStitchShell .tcTerritoryBadge{border-radius:12px;padding:4px 8px;background:var(--st-low);color:var(--st-green);font-size:11px;line-height:14px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;max-width:120px}
.tcStitchShell .neoTopNav{display:flex;align-items:center;justify-content:center;gap:24px;flex:1;min-width:0}
.tcStitchShell .neoTopNav button{border:0;padding:6px 0;background:none;color:var(--st-muted);font-size:13px;line-height:16px;font-weight:500}
.tcStitchShell .neoTopNav button[aria-current=page]{font-weight:600;color:var(--st-ink)}
.tcStitchShell .tcTopPublish{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-height:40px;padding:8px 16px;background:var(--st-green);color:#fff;border:0;border-radius:8px;font-size:13px;line-height:16px;max-width:190px}
.tcStitchShell .tcTopPublish svg{width:18px;height:18px}
.tcStitchShell .tcSiteMenu>summary{width:32px;min-height:32px;height:32px;padding:6px;gap:0;background:var(--st-ink);color:white;border:0;border-radius:12px}
.tcStitchShell .tcSiteMenu>summary>span{display:none}
.tcStitchShell .tcSiteMenuPanel{line-height:1.4}
.tcStitchShell .tcTerritorialStatus{background:var(--st-low);border-bottom:1px solid var(--st-line);font-size:12px;line-height:18px;color:var(--st-muted)}
.tcStitchShell .tcTerritorialStatus>div{max-width:1092px;margin:auto;padding:4px 40px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px}
.tcStitchShell .tcTerritorialStatus span{display:inline-flex;align-items:center;gap:6px}
.tcStitchShell .tcTerritorialStatus svg{width:14px;height:14px;color:var(--st-green)}
.tcStitchShell .neoHero{position:relative;display:block;width:100%;max-width:none;margin:0;padding:64px max(40px,calc((100% - 1012px)/2));border:0;border-radius:0;background:linear-gradient(180deg,var(--st-low),var(--st-surface));overflow:hidden;box-shadow:none;min-height:0}
.tcStitchShell .neoHero::before,.tcStitchShell .neoHero::after{content:none}
.tcStitchShell .neoHeroCopy{position:relative;z-index:1;max-width:1012px;margin:auto}
.tcStitchShell .tcStitchEyebrow{display:inline-flex;align-items:center;gap:8px;background:var(--st-high);color:var(--st-green);padding:4px 12px;border-radius:12px;font-size:13px;line-height:16px;font-weight:500;letter-spacing:.01em;text-transform:none}
.tcStitchShell .tcStitchEyebrow svg{width:16px;height:16px}
.tcStitchShell .neoHero h1{max-width:650px;margin:16px 0;font-size:54px;line-height:1.08;letter-spacing:-.03em;font-weight:700}
.tcStitchShell .neoHero h1 em{color:var(--st-green);font-style:normal;text-decoration:underline;text-decoration-color:var(--st-lime);text-decoration-thickness:4px;text-underline-offset:4px}
.tcStitchShell .neoHeroLead{max-width:600px;font-size:18px;line-height:28px;letter-spacing:-.01em;color:var(--st-muted);margin:16px 0 0}
.tcStitchShell .tcStitchHeroRadar{position:absolute;right:48px;top:-96px;width:520px;height:520px;opacity:.07;pointer-events:none;transform:none}
.tcStitchShell .tcStitchHeroRadar svg{width:100%;height:100%;stroke:var(--st-green);stroke-width:1.5}
.tcStitchShell .neoSearchDock{display:grid;grid-template-columns:5fr 4fr 3fr;gap:12px;width:100%;max-width:none;height:auto;padding:16px;margin:32px 0 0;background:#fff;border:1px solid var(--st-line);border-radius:16px;box-shadow:0 12px 36px -6px #10352914;align-items:center}
.tcStitchShell .neoSearchDock>label{display:flex;align-items:center;gap:12px;min-width:0;padding:10px 14px;background:var(--st-low);border:0;border-radius:8px;height:auto;min-height:52px}
.tcStitchShell .neoSearchDock label>span{display:flex;flex-direction:column;min-width:0;width:100%}
.tcStitchShell .neoSearchDock small{color:#66736a;font-size:11px;line-height:14px;font-weight:600;letter-spacing:.04em;text-transform:uppercase}
.tcStitchShell .neoSearchDock svg{width:22px;height:22px;color:var(--st-green)}
.tcStitchShell .neoSearchDock input,.tcStitchShell .neoSearchDock select{width:100%;min-width:0;height:22px;padding:0;background:none;border:0;border-radius:0;color:var(--st-ink);font-size:14px;line-height:22px;text-overflow:ellipsis}
.tcStitchShell .neoSearchDock>button{display:flex;align-items:center;justify-content:center;gap:8px;min-height:52px;border:0;border-radius:8px;padding:10px 12px;background:var(--st-ink);color:white;font:600 18px/26px 'Plus Jakarta Sans',sans-serif;box-shadow:0 4px 14px #10352929}
.tcStitchShell .neoSearchDock>button svg{color:inherit;width:20px;height:20px}
.tcStitchShell .tcSearchCategories{display:flex;align-items:center;flex-wrap:wrap;gap:8px;grid-column:1/-1;border-top:1px solid var(--st-low);padding:12px 4px 0;color:var(--st-muted);font-size:12px;line-height:18px;min-height:38px}
.tcStitchShell .tcSearchCategories>span{text-transform:uppercase;font-size:11px;letter-spacing:.04em;color:#66736a}
.tcStitchShell .tcSearchCategories button{border:0;border-radius:12px;padding:4px 10px;background:var(--st-surface);color:var(--st-ink);font-size:12px;line-height:18px}
.tcStitchShell .tcStitchRadarSummary{display:none}
.tcStitchShell .neoDiscover{display:flex;flex-direction:column;width:100%;max-width:1092px;margin:0 auto;padding:32px 40px 0;border:0;background:none;border-radius:0}
.tcStitchShell .neoDiscoverHead{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin:0 0 24px}
.tcStitchShell .neoDiscoverHead h2{display:flex;align-items:center;gap:8px;font-size:20px;line-height:28px;letter-spacing:-.005em;margin:0;color:var(--st-green);overflow-wrap:anywhere}
.tcStitchShell .neoDiscoverHead h2 svg{width:24px;height:24px}
.tcStitchShell .neoDiscoverHead p{font-size:14px;line-height:22px;color:var(--st-muted);margin:4px 0 0}
.tcStitchShell .tcCatalogCount{padding:6px 14px;border-radius:12px;background:var(--st-low);font-size:13px;line-height:16px;color:var(--st-green);flex-shrink:0}
.tcStitchShell .tcClearFilters{border:1px solid var(--st-line);border-radius:8px;background:white;padding:8px;font-size:12px;color:var(--st-green)}
.tcStitchShell .neoControlDeck{display:flex;flex-direction:column;gap:8px;margin:0 0 24px;background:none;border:0;padding:0;box-shadow:none;border-radius:0}
.tcStitchShell .neoFilters{position:relative;display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:0;background:none;border:0;box-shadow:none}
.tcStitchShell .neoFilterSearch{display:none}
.tcStitchShell .tcFiltersToggle{display:inline-flex;align-items:center;gap:6px;min-height:36px;padding:6px 12px;border:1px solid var(--st-line);background:#fff;color:var(--st-green);border-radius:8px;font-size:13px;line-height:16px}
.tcStitchShell .tcAdvancedFilters{display:none;width:100%;min-width:0;background:#fff;padding:12px;border:1px solid var(--st-line);border-radius:8px}
.tcStitchShell .tcAdvancedFilters[data-open=true]{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.tcStitchShell .tcAdvancedFilters label{display:flex;flex-direction:column;align-items:stretch;gap:4px;min-width:0;padding:8px;background:var(--st-low);border:0;border-radius:8px;font-size:12px;line-height:18px}
.tcStitchShell .tcAdvancedFilters select{width:100%;max-width:none;border:0;background:none;padding:4px 0;color:var(--st-ink);font-size:14px}
.tcStitchShell .tcAdvancedFilters>button{display:flex;align-items:center;justify-content:center;gap:6px;min-height:44px;padding:8px;color:var(--st-green);background:var(--st-low);border:1px solid var(--st-line);border-radius:8px;font-size:12px}
.tcStitchShell .tcCommuneRail,.tcStitchShell .tcCategoryRail{display:flex;gap:8px;overflow-x:auto;padding:0 0 4px;scrollbar-width:none}
.tcStitchShell .tcCommuneRail button,.tcStitchShell .tcCategoryRail button{flex-shrink:0;white-space:nowrap;border:1px solid var(--st-line);border-radius:12px;background:#fff;padding:8px 16px;color:var(--st-ink);font-size:13px;line-height:16px;font-weight:500}
.tcStitchShell .tcCommuneRail button.active,.tcStitchShell .tcCategoryRail button.active{background:var(--st-ink);color:white;border-color:var(--st-ink)}
.tcStitchShell .tcCategoryRail{display:none}
.tcStitchShell .neoJobsGrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-items:stretch;gap:16px}
.tcStitchShell .neoJobCard{position:relative;display:flex;min-width:0;min-height:276px;border:1px solid #d7dfd480;border-radius:8px;background:white;color:var(--st-ink);box-shadow:none;overflow:hidden}
.tcStitchShell .neoJobCard:hover{border-color:var(--st-green);box-shadow:0 8px 24px -4px #1035290f;transform:none}
.tcStitchShell .neoJobBody{display:flex;flex-direction:column;min-width:0;width:100%;padding:20px}
.tcStitchShell .neoJobTop{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;min-width:0}
.tcStitchShell .neoJobPlace{display:inline-flex;align-items:center;gap:4px;max-width:60%;min-width:0;padding:2px 8px;border-radius:12px;background:var(--st-low);color:var(--st-green);font-size:11px;line-height:14px;letter-spacing:.04em;font-weight:600;text-transform:uppercase;overflow-wrap:anywhere}
.tcStitchShell .neoJobPlace svg{width:12px;height:12px}
.tcStitchShell .neoJobState{position:static;display:inline-flex;max-width:45%;padding:0;border:0;background:transparent;font-size:11px;line-height:14px;font-weight:500;color:#66736a;white-space:normal;text-align:right}
.tcStitchShell .neoJobState.pending{color:#85502b}
.tcStitchShell .neoJobCard h3{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;font-size:20px;line-height:28px;font-weight:600;letter-spacing:-.005em;margin:8px 0 0;min-height:26px;color:var(--st-ink)}
.tcStitchShell .neoJobCompany{margin:4px 0 0;font-size:14px;line-height:22px;color:var(--st-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tcStitchShell .neoSalary{margin-top:4px;font-size:13px;line-height:18px;color:var(--st-green)}
.tcStitchShell .tcCardTags{display:flex;flex-wrap:wrap;gap:6px;margin:16px 0 0}
.tcStitchShell .tcCardTags span{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding:3px 8px;background:var(--st-low);color:var(--st-muted);font-size:11px;line-height:14px;border-radius:3px}
.tcStitchShell .tcOfferActionRow{display:flex;align-items:center;justify-content:space-between;gap:8px;border-top:1px solid var(--st-low);padding:16px 0 0;margin:24px 0 0;margin-top:auto;min-height:56px}
.tcStitchShell .neoJobFacts{min-width:0;flex:1;display:block;margin:0;padding:0}
.tcStitchShell .neoJobFacts>span{min-width:0;display:flex;flex-direction:column;gap:2px}
.tcStitchShell .neoJobFacts small,.tcStitchShell .neoJobFacts b{display:block;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;line-height:14px;font-weight:400;color:#66736a}
.tcStitchShell .neoJobFoot{display:block;margin:0;padding:0;border:0}
.tcStitchShell .neoJobFoot button{display:inline-flex;align-items:center;justify-content:center;gap:4px;border:0;border-radius:4px;padding:6px 12px;min-height:32px;background:var(--st-low);color:var(--st-ink);font-size:13px;line-height:16px;font-weight:600;white-space:nowrap}
.tcStitchShell .neoJobFoot svg{width:16px;height:16px}
.tcStitchShell .tcPosterThumb{position:absolute;right:20px;bottom:64px;width:32px;height:32px;float:none;margin:0;z-index:1}
.tcStitchShell .neoOwnActions{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}
.tcStitchShell .neoOwnActions button{min-height:40px;padding:8px;font-size:12px;border:1px solid var(--st-line);border-radius:4px;background:white;color:var(--st-ink)}
.tcStitchShell .tcResultsPagination{display:flex;justify-content:center;align-items:center;flex-wrap:wrap;gap:12px;padding:16px 0;font-size:12px;line-height:18px;color:var(--st-muted)}
.tcStitchShell .tcResultsPagination button,.tcStitchShell .neoLoadMore button{min-height:40px;padding:8px 12px;border:1px solid var(--st-line);border-radius:8px;background:white;color:var(--st-green);font-size:12px}
.tcStitchShell .neoLoadMore{display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;padding:12px}
.tcStitchShell .neoEmpty{display:flex;align-items:center;flex-direction:column;gap:12px;border:1px solid var(--st-line);border-radius:8px;background:white;padding:24px;color:var(--st-muted);text-align:center}
.tcStitchShell .tcStitchAlert{display:flex;align-items:center;gap:12px;width:calc(100% - 80px);max-width:1012px;margin:24px auto 32px;padding:16px;background:var(--st-low);border:1px solid #26744733;border-radius:8px}
.tcStitchShell .tcStitchAlert>svg{color:var(--st-green);width:24px;height:24px}
.tcStitchShell .tcStitchAlert>div{flex:1;display:flex;flex-direction:column}
.tcStitchShell .tcStitchAlert b{font-size:13px;line-height:16px;font-weight:600}
.tcStitchShell .tcStitchAlert span{font-size:12px;line-height:18px;color:var(--st-muted)}
.tcStitchShell .tcStitchAlert button{display:inline-flex;align-items:center;gap:6px;border:0;background:none;color:var(--st-green);font-size:13px;line-height:16px;font-weight:600}
